-- Condições do livro no compêndio. Ficam fora do gerenciador até o Mestre adicionar.
-- Não duplica nomes que já existam.
insert into public.condicoes (nome, descricao, efeitos, origem, status)
select v.nome, v.descricao, v.efeitos, 'compendio', 'aprovada'
from (values
  ($c$Abalado$c$, $c$O personagem sofre –2 em testes de perícia. Se ficar abalado novamente, em vez disso fica apavorado. Medo.$c$, $c$[{"type": "skill", "skills": ["Acrobacia", "Adestramento", "Atletismo", "Atuação", "Cavalgar", "Conhecimento", "Cura", "Diplomacia", "Enganação", "Fortitude", "Furtividade", "Guerra", "Iniciativa", "Intimidação", "Intuição", "Investigação", "Jogatina", "Ladinagem", "Luta", "Misticismo", "Nobreza", "Ofício", "Percepção", "Pilotagem", "Pontaria", "Reflexos", "Religião", "Sobrevivência", "Vontade"], "bonus": -2}]$c$::jsonb),
  ($c$Agarrado$c$, $c$O personagem fica desprevenido e imóvel, sofre –2 em testes de ataque e só pode atacar com armas leves. Ataques à distância contra um alvo envolvido em uma manobra agarrar têm 50% de chance de acertar o alvo errado. Movimento.$c$, $c$[{"type": "ac", "bonus": -5}, {"type": "skill", "skill": "Reflexos", "bonus": -5}, {"type": "attack", "bonusHit": -2, "bonusDamage": ""}]$c$::jsonb),
  ($c$Alquebrado$c$, $c$O custo em pontos de mana das habilidades do personagem aumenta em +1. Mental.$c$, $c$[]$c$::jsonb),
  ($c$Apavorado$c$, $c$O personagem sofre –5 em testes de perícia e não pode se aproximar voluntariamente da fonte do medo. Medo.$c$, $c$[{"type": "skill", "skills": ["Acrobacia", "Adestramento", "Atletismo", "Atuação", "Cavalgar", "Conhecimento", "Cura", "Diplomacia", "Enganação", "Fortitude", "Furtividade", "Guerra", "Iniciativa", "Intimidação", "Intuição", "Investigação", "Jogatina", "Ladinagem", "Luta", "Misticismo", "Nobreza", "Ofício", "Percepção", "Pilotagem", "Pontaria", "Reflexos", "Religião", "Sobrevivência", "Vontade"], "bonus": -5}]$c$::jsonb),
  ($c$Atordoado$c$, $c$O personagem fica desprevenido e não pode fazer ações. Mental.$c$, $c$[{"type": "ac", "bonus": -5}, {"type": "skill", "skill": "Reflexos", "bonus": -5}]$c$::jsonb),
  ($c$Caído$c$, $c$O personagem sofre –5 em ataques corpo a corpo e seu deslocamento é reduzido a 1,5m. Além disso, sofre –5 na Defesa contra ataques corpo a corpo e recebe +5 na Defesa contra ataques à distância (cumulativos com outras condições).$c$, $c$[]$c$::jsonb),
  ($c$Cego$c$, $c$O personagem fica desprevenido e lento, não pode fazer testes de Percepção para observar e sofre –5 em testes de perícias baseadas em Força ou Destreza. Todos os alvos de seus ataques recebem camuflagem total. Você é considerado cego enquanto estiver em uma área de escuridão total, a menos que algo lhe permita perceber no escuro. Sentidos.$c$, $c$[{"type": "ac", "bonus": -5}, {"type": "skill", "skill": "Reflexos", "bonus": -5}, {"type": "skill", "skills": ["Acrobacia", "Atletismo", "Cavalgar", "Furtividade", "Iniciativa", "Ladinagem", "Luta", "Pilotagem", "Pontaria", "Reflexos"], "bonus": -5}]$c$::jsonb),
  ($c$Confuso$c$, $c$O personagem comporta-se de modo aleatório. Role 1d6 no início de seus turnos: 1) Movimenta-se em uma direção escolhida por uma rolagem de 1d8; 2-3) Não pode fazer ações, e fica balbuciando incoerentemente; 4-5) Usa a arma que estiver empunhando para atacar a criatura mais próxima, ou a si mesmo se estiver sozinho (nesse caso, apenas role o dano); 6) A condição termina e pode agir normalmente. Mental.$c$, $c$[]$c$::jsonb),
  ($c$Debilitado$c$, $c$O personagem sofre –5 em testes de Força, Destreza e Constituição e de perícias baseadas nesses atributos. Se o personagem ficar debilitado novamente, em vez disso fica inconsciente.$c$, $c$[{"type": "skill", "skills": ["Acrobacia", "Atletismo", "Cavalgar", "Fortitude", "Furtividade", "Iniciativa", "Ladinagem", "Luta", "Pilotagem", "Pontaria", "Reflexos"], "bonus": -5}]$c$::jsonb),
  ($c$Desprevenido$c$, $c$O personagem sofre –5 na Defesa e em Reflexos. Você fica desprevenido contra inimigos que não possa perceber.$c$, $c$[{"type": "ac", "bonus": -5}, {"type": "skill", "skill": "Reflexos", "bonus": -5}]$c$::jsonb),
  ($c$Doente$c$, $c$Sob efeito de uma doença. Metabolismo.$c$, $c$[]$c$::jsonb),
  ($c$Em Chamas$c$, $c$O personagem está pegando fogo. No início de seus turnos, sofre 1d6 pontos de dano de fogo. O personagem pode gastar uma ação padrão para apagar o fogo com as mãos. Imersão em água também apaga as chamas.$c$, $c$[]$c$::jsonb),
  ($c$Enfeitiçado$c$, $c$O personagem se torna prestativo em relação à fonte da condição. Ele não fica sob controle da fonte, mas percebe suas palavras e ações da maneira mais favorável possível. A fonte da condição recebe +10 em testes de Diplomacia com o personagem. Mental.$c$, $c$[]$c$::jsonb),
  ($c$Enjoado$c$, $c$O personagem só pode realizar uma ação padrão ou de movimento (não ambas) por rodada. Ele pode gastar uma ação padrão para fazer uma investida, mas pode avançar no máximo seu deslocamento (e não o dobro). Metabolismo.$c$, $c$[]$c$::jsonb),
  ($c$Enredado$c$, $c$O personagem fica lento, vulnerável e sofre –2 em testes de ataque. Movimento.$c$, $c$[{"type": "ac", "bonus": -2}, {"type": "attack", "bonusHit": -2, "bonusDamage": ""}]$c$::jsonb),
  ($c$Envenenado$c$, $c$O efeito desta condição varia de acordo com o veneno. Pode ser perda de vida recorrente ou outra condição (como fraco ou enjoado). Perda de vida recorrente por venenos é cumulativa. Veneno.$c$, $c$[]$c$::jsonb),
  ($c$Esmorecido$c$, $c$O personagem sofre –5 em testes de Inteligência, Sabedoria e Carisma e de perícias baseadas nesses atributos. Mental.$c$, $c$[{"type": "skill", "skills": ["Adestramento", "Atuação", "Conhecimento", "Cura", "Diplomacia", "Enganação", "Guerra", "Intimidação", "Intuição", "Investigação", "Jogatina", "Misticismo", "Nobreza", "Ofício", "Percepção", "Religião", "Sobrevivência", "Vontade"], "bonus": -5}]$c$::jsonb),
  ($c$Exausto$c$, $c$O personagem fica debilitado, lento e vulnerável. Se ficar exausto novamente, em vez disso fica inconsciente. Cansaço.$c$, $c$[{"type": "skill", "skills": ["Acrobacia", "Atletismo", "Cavalgar", "Fortitude", "Furtividade", "Iniciativa", "Ladinagem", "Luta", "Pilotagem", "Pontaria", "Reflexos"], "bonus": -5}, {"type": "ac", "bonus": -2}]$c$::jsonb),
  ($c$Fascinado$c$, $c$Com a atenção presa em alguma coisa. O personagem sofre –5 em Percepção e não pode fazer ações, exceto observar aquilo que o fascinou. Esta condição é anulada por ações hostis contra o personagem ou se o que o fascinou não estiver mais visível. Balançar uma criatura fascinada para tirá-la desse estado gasta uma ação padrão. Mental.$c$, $c$[{"type": "skill", "skill": "Percepção", "bonus": -5}]$c$::jsonb),
  ($c$Fatigado$c$, $c$O personagem fica fraco e vulnerável. Se ficar fatigado novamente, em vez disso fica exausto. Cansaço.$c$, $c$[{"type": "skill", "skills": ["Acrobacia", "Atletismo", "Cavalgar", "Fortitude", "Furtividade", "Iniciativa", "Ladinagem", "Luta", "Pilotagem", "Pontaria", "Reflexos"], "bonus": -2}, {"type": "ac", "bonus": -2}]$c$::jsonb),
  ($c$Fraco$c$, $c$O personagem sofre –2 em testes de Força, Destreza e Constituição e de perícias baseadas nesses atributos. Se ficar fraco novamente, em vez disso fica debilitado.$c$, $c$[{"type": "skill", "skills": ["Acrobacia", "Atletismo", "Cavalgar", "Fortitude", "Furtividade", "Iniciativa", "Ladinagem", "Luta", "Pilotagem", "Pontaria", "Reflexos"], "bonus": -2}]$c$::jsonb),
  ($c$Frustrado$c$, $c$O personagem sofre –2 em testes de Inteligência, Sabedoria e Carisma e de perícias baseadas nesses atributos. Se ficar frustrado novamente, em vez disso fica esmorecido. Mental.$c$, $c$[{"type": "skill", "skills": ["Adestramento", "Atuação", "Conhecimento", "Cura", "Diplomacia", "Enganação", "Guerra", "Intimidação", "Intuição", "Investigação", "Jogatina", "Misticismo", "Nobreza", "Ofício", "Percepção", "Religião", "Sobrevivência", "Vontade"], "bonus": -2}]$c$::jsonb),
  ($c$Imóvel$c$, $c$Todas as formas de deslocamento do personagem são reduzidas a 0m. Movimento.$c$, $c$[]$c$::jsonb),
  ($c$Inconsciente$c$, $c$O personagem fica indefeso e não pode fazer ações, incluindo reações (mas ainda pode fazer testes que sejam naturalmente feitos quando se está inconsciente, como testes de Constituição para estabilizar sangramento). Balançar uma criatura para acordá-la gasta uma ação padrão.$c$, $c$[{"type": "ac", "bonus": -10}, {"type": "skill", "skill": "Reflexos", "bonus": -5}]$c$::jsonb),
  ($c$Indefeso$c$, $c$O personagem fica desprevenido, mas sofre –10 na Defesa, falha automaticamente em testes de Reflexos e pode sofrer golpes de misericórdia.$c$, $c$[{"type": "ac", "bonus": -10}, {"type": "skill", "skill": "Reflexos", "bonus": -5}]$c$::jsonb),
  ($c$Lento$c$, $c$Todas as formas de deslocamento do personagem são reduzidas à metade (arredonde para baixo para o primeiro incremento de 1,5m) e ele não pode correr ou fazer investidas. Movimento.$c$, $c$[]$c$::jsonb),
  ($c$Ofuscado$c$, $c$O personagem sofre –2 em testes de ataque e de Percepção. Sentidos.$c$, $c$[{"type": "attack", "bonusHit": -2, "bonusDamage": ""}, {"type": "skill", "skill": "Percepção", "bonus": -2}]$c$::jsonb),
  ($c$Paralisado$c$, $c$Fica imóvel e indefeso e só pode realizar ações puramente mentais. Movimento.$c$, $c$[{"type": "ac", "bonus": -10}, {"type": "skill", "skill": "Reflexos", "bonus": -5}]$c$::jsonb),
  ($c$Pasmo$c$, $c$Não pode fazer ações. Mental.$c$, $c$[]$c$::jsonb),
  ($c$Petrificado$c$, $c$O personagem fica inconsciente e recebe redução de dano 8. Metamorfose.$c$, $c$[{"type": "ac", "bonus": -10}, {"type": "skill", "skill": "Reflexos", "bonus": -5}]$c$::jsonb),
  ($c$Sangrando$c$, $c$No início de seu turno, o personagem deve fazer um teste de Constituição (CD 15). Se falhar, perde 1d6 pontos de vida e continua sangrando. Se passar, remove essa condição. Metabolismo.$c$, $c$[]$c$::jsonb),
  ($c$Sobrecarregado$c$, $c$O personagem sofre penalidade de armadura –5 e seu deslocamento é reduzido –3m. Movimento.$c$, $c$[{"type": "movement", "bonus": -3}]$c$::jsonb),
  ($c$Surdo$c$, $c$O personagem não pode fazer testes de Percepção para ouvir e sofre –5 em testes de Iniciativa. Além disso, é considerado em condição ruim para lançar magias. Sentidos.$c$, $c$[{"type": "skill", "skill": "Iniciativa", "bonus": -5}]$c$::jsonb),
  ($c$Surpreendido$c$, $c$O personagem fica desprevenido e não pode fazer ações.$c$, $c$[{"type": "ac", "bonus": -5}, {"type": "skill", "skill": "Reflexos", "bonus": -5}]$c$::jsonb),
  ($c$Vulnerável$c$, $c$O personagem sofre –2 na Defesa.$c$, $c$[{"type": "ac", "bonus": -2}]$c$::jsonb)
) as v (nome, descricao, efeitos)
where not exists (select 1 from public.condicoes c where lower(c.nome) = lower(v.nome));
